            $(document).ready(function () {
                $('#top-link-block').on('click', function () {
                    $('html,body').animate({scrollTop: 0}, 'slow');
                    return false;
                });
                /*
                $.ajaxPrefilter(function(options, original_Options, jqXHR) {
                    options.async = true;
                });
                */
            });

			function content_status(content, status){
				//status of all in one success, info, warning, danger(default)
				if (typeof status === 'undefined') {
					status = 'danger';
				}
				return ('<div class="alert alert-' + status + '">' + content + '</div>');
			}

			function show_notify(content, title){
				if (typeof title === 'undefined') {
					title = 'Thông báo';
				}
				$('#notify-modal').find('.modal-title').text(title);
				$('#notify-modal').find('.modal-body').html(content);
				$('#notify-modal').modal('show');
			}

			function hide_notify(){
				$('#notify-modal').modal('hide');
			}

			$('#notify-modal').on('hide.bs.modal', function (event) {
				$('#notify-modal').find('.modal-title').text('Thông báo');
				$('#notify-modal').find('.modal-body').html('');
			});
			$('#modal_profile').on('show.bs.modal', function () {
				$.ajax({
				    url: base_url + 'users/get-ajax',
				    type: 'POST',
				    data: {
				    	ajax: true
				    },
				    dataType: 'json',
				    success: function(response) {
				    	console.log(response);
				        if (response.status == 'success') {
				            var content = response.content;
				            var $this = $('#f-profile');
				            $('#link-share-username').val(content.link_share);
				            $this.find('input[name=full_name]').val(content.full_name);
				            $this.find('input[name=phone]').val(content.phone);
				            $this.find('input[name=address]').val(content.address);
				        }else{
				            alert(response.message);
				        }
				    },
				    error: function(e) {
				        console.log('Lỗi: ' + e.responseText);
				    }
				});
			});

			$(document).on('click', '.btn-submit-profile', function () {
				$("#f-profile").trigger("submit");
			});

			$(document).on('submit', '#f-profile', function () {
				// console.log(1235);
				$('#modal_profile').modal('hide');
				return false;
			});
        </script>
